import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as a,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Codex Remote","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/codex/codex-remote.md","filePath":"products/ai-coding/codex/codex-remote.md","lastUpdated":1787046041000}'),n={name:"products/ai-coding/codex/codex-remote.md"};function s(d,e,p,i,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="codex-remote" tabindex="-1">Codex Remote <a class="header-anchor" href="#codex-remote" aria-label="Permalink to &quot;Codex Remote&quot;">​</a></h1><blockquote><p>A <strong>tutorial</strong> — pair the ChatGPT mobile app with a Mac or Windows host, then start, steer, approve, and review Codex tasks from your phone. The <strong>connected computer</strong> runs the work. Remote is not Cloud.</p><p>Official landing: <a href="https://learn.chatgpt.com/codex/remote" target="_blank" rel="noreferrer">learn.chatgpt.com/codex/remote</a>. Setup and security: <a href="https://learn.chatgpt.com/docs/remote-connections" target="_blank" rel="noreferrer">Remote connections</a>.</p></blockquote><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Need</th><th>Requirement</th></tr></thead><tbody><tr><td>Host</td><td>Latest <a href="https://learn.chatgpt.com/docs/app" target="_blank" rel="noreferrer">ChatGPT desktop app</a> on macOS or Windows, awake and online</td></tr><tr><td>Phone</td><td>Latest ChatGPT iOS or Android app, with <strong>Remote</strong> visible</td></tr><tr><td>Account</td><td>Same ChatGPT account <strong>and</strong> workspace on both devices</td></tr><tr><td>Access</td><td>Codex on that account; workspace admins may need to enable Remote Control</td></tr></tbody></table><p>Availability depends on rollout and workspace settings. You cannot start pairing from the CLI or the IDE extension.</p><p><strong>Learning objectives</strong>: pair one phone with one host; start or continue a task; approve a command; review a diff; know why the host must stay awake.</p><p><strong>Non-goals</strong>: hosted environments (<a href="./codex-cloud.html">Cloud</a>); <code>codex app-server</code> JSON-RPC (<a href="https://learn.chatgpt.com/docs/app-server" target="_blank" rel="noreferrer">App Server</a>); desktop Work vs Codex mapping (<a href="./chatgpt-work.html">Work</a>).</p><h2 id="what-remote-is-—-and-is-not" tabindex="-1">What Remote is — and is not <a class="header-anchor" href="#what-remote-is-—-and-is-not" aria-label="Permalink to &quot;What Remote is — and is not&quot;">​</a></h2><p>Remote is a <strong>control surface</strong>. Your phone sends prompts, approvals, and follow-ups. The host provides the repo, shell, plugins, Computer Use, browser, credentials, and sandbox.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Phone (ChatGPT mobile · Remote)</span></span>
<span class="line"><span>        │  prompts / approvals / review</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Host (ChatGPT desktop · Mac or Windows)</span></span>
<span class="line"><span>        │  files, shell, plugins, Computer Use</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Optional: SSH project on another machine</span></span></code></pre></div><p>It is <strong>not</strong>:</p><ul><li><a href="./codex-cloud.html">Codex Cloud</a>. Cloud runs on OpenAI-hosted machines and does not need your laptop.</li><li>A public listener. Pairing uses a relay; do not expose <code>codex app-server</code> to the internet.</li><li>A way to unlock a Windows desktop for Computer Use while you use that same session. Windows Computer Use takes the foreground.</li></ul><h2 id="step-1-—-start-setup-on-the-host" tabindex="-1">Step 1 — Start setup on the host <a class="header-anchor" href="#step-1-—-start-setup-on-the-host" aria-label="Permalink to &quot;Step 1 — Start setup on the host&quot;">​</a></h2><p>On the Mac or Windows PC:</p><ol><li>Open the ChatGPT desktop app.</li><li>Go to <strong>Settings → Connections → Control this Mac or PC</strong>.</li><li>Select <strong>Set up</strong> or <strong>Add</strong>.</li><li>Approve remote access and finish any verification.</li></ol><p>Only pair devices you own and trust.</p><h2 id="step-2-—-scan-the-qr-code" tabindex="-1">Step 2 — Scan the QR code <a class="header-anchor" href="#step-2-—-scan-the-qr-code" aria-label="Permalink to &quot;Step 2 — Scan the QR code&quot;">​</a></h2><p>Scan the code with the phone. Sign in to the <strong>same</strong> account and workspace. Complete MFA / SSO / passkey if asked. The host then appears under <strong>Remote</strong>.</p><p>Pair every phone with every host you want it to control. Existing connections unused since 2026-06-08 need a fresh pair after you update both apps.</p><h2 id="step-3-—-work-from-the-phone" tabindex="-1">Step 3 — Work from the phone <a class="header-anchor" href="#step-3-—-work-from-the-phone" aria-label="Permalink to &quot;Step 3 — Work from the phone&quot;">​</a></h2><p>Open <strong>Remote</strong>, pick the connected computer, start a task or continue one.</p><p>Keep the host <strong>awake and online</strong>. Closing the desktop app, sleeping, or losing the network stops Remote.</p><table tabindex="0"><thead><tr><th>Host detail</th><th>Constraint</th></tr></thead><tbody><tr><td>Mac laptop, lid open, power connected</td><td>Remote can stay available</td></tr><tr><td>Mac laptop, lid closed</td><td>Also connect an external display</td></tr><tr><td>Choosing <strong>Sleep</strong></td><td>Remote stops</td></tr><tr><td>Windows + Computer Use</td><td>Keep the session unlocked; Computer Use owns the foreground</td></tr></tbody></table><h2 id="what-you-do-from-the-phone" tabindex="-1">What you do from the phone <a class="header-anchor" href="#what-you-do-from-the-phone" aria-label="Permalink to &quot;What you do from the phone&quot;">​</a></h2><ol><li><strong>See tasks</strong> on the connected computer, including when input is needed.</li><li><strong>Approve</strong> commands and actions before Codex continues on that host.</li><li><strong>Review</strong> responses, changed files, diffs, and test results.</li><li><strong>Start</strong> a new task against a connected computer and project.</li></ol><p>The host’s sandbox, approval policy, and organization settings still apply.</p><h2 id="remote-vs-cloud-vs-app-server" tabindex="-1">Remote vs Cloud vs app-server <a class="header-anchor" href="#remote-vs-cloud-vs-app-server" aria-label="Permalink to &quot;Remote vs Cloud vs app-server&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Remote</th><th>Cloud</th><th><code>codex app-server</code></th></tr></thead><tbody><tr><td>Where work runs</td><td>Your paired Mac / Windows (or its SSH project)</td><td>OpenAI-hosted env</td><td>A process you start, usually for a custom client</td></tr><tr><td>Needs the laptop awake</td><td><strong>Yes</strong></td><td>No</td><td>Depends on that process</td></tr><tr><td>Typical entry</td><td>ChatGPT mobile <strong>Remote</strong></td><td><a href="https://chatgpt.com/codex" target="_blank" rel="noreferrer">chatgpt.com/codex</a></td><td><code>codex app-server --listen …</code></td></tr><tr><td>Use when</td><td>Approve / steer a local session from the phone</td><td>Parallel hosted jobs</td><td>Embed Codex in a product</td></tr></tbody></table><p>App Server protocol: <a href="https://learn.chatgpt.com/docs/app-server" target="_blank" rel="noreferrer">Codex App Server</a>. SSH projects and chat handoff: <a href="https://learn.chatgpt.com/docs/remote-connections" target="_blank" rel="noreferrer">Remote connections</a>.</p><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pitfall</th><th>What happens</th><th>Do this instead</th></tr></thead><tbody><tr><td>Pairing different workspaces</td><td>Host never appears</td><td>Same account <strong>and</strong> workspace</td></tr><tr><td>Letting the laptop sleep</td><td>Session drops</td><td>Keep the host awake; or use <a href="./codex-cloud.html">Cloud</a></td></tr><tr><td>Expecting Cloud-style isolation</td><td>Phone drives <strong>your</strong> machine</td><td>Do not treat Remote as a sandbox</td></tr><tr><td>Exposing app-server on a public port</td><td>Unauthenticated listeners during rollout</td><td>Use official Remote pairing or <code>wss://</code> + auth; prefer a VPN</td></tr><tr><td>Looking for setup in the CLI</td><td>There is no CLI pairing flow</td><td>Start from the desktop app</td></tr></tbody></table><h2 id="real-world-use" tabindex="-1">Real-world use <a class="header-anchor" href="#real-world-use" aria-label="Permalink to &quot;Real-world use&quot;">​</a></h2><p>You kick off a local test-and-fix in desktop Codex before leaving the office. On the train you open <strong>Remote</strong>, approve one <code>pnpm test</code> run, and read the diff. If the laptop will sleep, do not use Remote — send the job to <a href="./codex-cloud.html">Cloud</a> before you close the lid.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ol><li>Full pairing, SSH, handoff, troubleshooting → <a href="https://learn.chatgpt.com/docs/remote-connections" target="_blank" rel="noreferrer">Remote connections</a></li><li>Hosted jobs that survive sleep → <a href="./codex-cloud.html">Cloud</a></li><li>Desktop Chat / Work / Codex → <a href="./chatgpt-work.html">Work</a> · <a href="./codex-ai.html">product line</a></li></ol><h2 id="official-sources" tabindex="-1">Official sources <a class="header-anchor" href="#official-sources" aria-label="Permalink to &quot;Official sources&quot;">​</a></h2><ul><li><a href="https://learn.chatgpt.com/codex/remote" target="_blank" rel="noreferrer">Codex Remote (landing)</a></li><li><a href="https://learn.chatgpt.com/docs/remote" target="_blank" rel="noreferrer">Remote (docs)</a></li><li><a href="https://learn.chatgpt.com/docs/remote-connections" target="_blank" rel="noreferrer">Remote connections</a></li><li><a href="https://learn.chatgpt.com/docs/app" target="_blank" rel="noreferrer">ChatGPT desktop app</a></li><li><a href="https://learn.chatgpt.com/docs/app-server" target="_blank" rel="noreferrer">App Server</a></li></ul>`,37)])])}const b=t(n,[["render",s]]);export{f as __pageData,b as default};
